def is_palindrome(text):
    left, right = 0, len(text) - 1
    while left < right:
        if text[left] != text[right]:
            return False
        left += 1
        right -= 1
    return True

function is_palindrome(text) {
  let left = 0, right = text.length - 1;
  while (left < right) {
    if (text[left++] !== text[right--]) return false;
  }
  return true;
}

