def permutations(text):
    frequencies = {}
    for char in text:
        frequencies[char] = frequencies.get(char, 0) + 1
    out = []
    def visit(prefix):
        if len(prefix) == len(text):
            out.append(prefix)
            return
        for char in frequencies:
            if frequencies[char]:
                frequencies[char] -= 1
                visit(prefix + char)
                frequencies[char] += 1
    visit('')
    return out

function permutations(text) {
  const chars = Array.from(text), counts = new Map(), out = [];
  for (const char of chars) counts.set(char, (counts.get(char) ?? 0) + 1);
  function visit(path) {
    if (path.length === chars.length) { out.push(path.join('')); return; }
    for (const [char, count] of counts) if (count > 0) {
      counts.set(char, count - 1); path.push(char); visit(path); path.pop(); counts.set(char, count);
    }
  }
  visit([]);
  return out;
}

def reverse_range(chars, lo, hi):
    while lo < hi:
        chars[lo], chars[hi] = chars[hi], chars[lo]
        lo += 1
        hi -= 1

def reverse_words(text):
    chars = list(text)
    reverse_range(chars, 0, len(chars) - 1)
    start = 0
    while start < len(chars):
        if chars[start] == ' ':
            start += 1
            continue
        end = start
        while end < len(chars) and chars[end] != ' ':
            end += 1
        reverse_range(chars, start, end - 1)
        start = end
    return ''.join(chars)

function reverse_range(chars, lo, hi) {
  while (lo < hi) { [chars[lo], chars[hi]] = [chars[hi], chars[lo]]; lo++; hi--; }
}
function reverse_words(text) {
  const chars = Array.from(text);
  reverse_range(chars, 0, chars.length - 1);
  let start = 0;
  while (start < chars.length) {
    if (chars[start] === ' ') { start++; continue; }
    let end = start;
    while (end < chars.length && chars[end] !== ' ') end++;
    reverse_range(chars, start, end - 1);
    start = end;
  }
  return chars.join('');
}

module enabled_mod_six_counter(input clk,rst,enable, output reg [2:0] count);
always @(posedge clk) begin
    if (rst) count <= 3'd0;
    else if (count >= 3'd6) count <= 3'd0;
    else if (enable) count <= count == 3'd5 ? 3'd0 : count + 3'd1;
end
endmodule

